/* ─── CURSOR ─── */
function Cursor() {
  const [pos,setPos]=useState({x:0,y:0});
  const [ring,setRing]=useState({x:0,y:0});
  const [big,setBig]=useState(false);
  const raf=useRef(null);
  const tgt=useRef({x:0,y:0});
  useEffect(()=>{
    const mv=e=>{setPos({x:e.clientX,y:e.clientY});tgt.current={x:e.clientX,y:e.clientY};};
    window.addEventListener('mousemove',mv);
    const tick=()=>{setRing(p=>({x:p.x+(tgt.current.x-p.x)*0.13,y:p.y+(tgt.current.y-p.y)*0.13}));raf.current=requestAnimationFrame(tick);};
    raf.current=requestAnimationFrame(tick);
    return()=>{window.removeEventListener('mousemove',mv);cancelAnimationFrame(raf.current);};
  },[]);
  useEffect(()=>{
    const ov=()=>setBig(true),ot=()=>setBig(false);
    const els=document.querySelectorAll('button,input,textarea,a');
    els.forEach(el=>{el.addEventListener('mouseenter',ov);el.addEventListener('mouseleave',ot);});
    return()=>els.forEach(el=>{el.removeEventListener('mouseenter',ov);el.removeEventListener('mouseleave',ot);});
  });
  return(
    <>
      <div className={`cursor${big?' big':''}`} style={{left:pos.x+'px',top:pos.y+'px'}}/>
      <div className={`cursor-ring${big?' big':''}`} style={{left:ring.x+'px',top:ring.y+'px'}}/>
    </>
  );
}

/* ─── APP ─── */
export default function App() {
  const [page,setPage]=useState('home');
  const toast=useToast();
  const go=useCallback(id=>{setPage(id);window.scrollTo({top:0,behavior:'smooth'});},[]);
  const pages={home:<HomePage setPage={go}/>,parts:<PartsPage toast={toast} setPage={go}/>,services:<ServicesPage setPage={go}/>,gallery:<GalleryPage/>,contact:<ContactPage toast={toast}/>};
  return(
    <>
      <style>{CSS.replace('var(--wm-logo)',`url('${LOGO_TRANSPARENT}')`)}</style>
      <Cursor/>
      <div className="grain"/>
      <div className="watermark" style={{
        backgroundImage:`url('${LOGO_TRANSPARENT}')`,
        backgroundRepeat:'no-repeat',
        backgroundPosition:'center center',
        backgroundSize:'contain',
        imageRendering:'crisp-edges',
        WebkitImageRendering:'-webkit-optimize-contrast',
        filter:'contrast(1.6) brightness(0.4) saturate(1.2)',
        opacity:0.12,
      }}/>
      <Nav page={page} setPage={go}/>
      <main style={{paddingTop:'72px',minHeight:'100vh',position:'relative',zIndex:1}}>
        {pages[page]}
      </main>
      <Footer setPage={go}/>
      {toast.visible&&(
        <div style={{position:'fixed',bottom:'28px',right:'28px',zIndex:9000,background:'#ffffff',border:'1px solid #c8102e',color:'#111111',fontSize:'0.82rem',padding:'14px 22px',borderRadius:'4px',display:'flex',alignItems:'center',gap:'10px',boxShadow:'0 12px 40px rgba(0,0,0,.25),0 0 20px rgba(200,16,46,0.25)',animation:'pgIn .4s ease'}}>
          ✅ <span>{toast.msg}</span>
        </div>
      )}
    </>
  );
}
